#!/usr/bin/env bash
set -euo pipefail

# Build a mean FA image in the existing healthy-control FOD template space.
# Adapted from f_create_template_mean_fa.sh; retains the original MRtrix operations:
# mrtransform -warp_full -> mrcat -> mrmath -> mrcalc -> mrconvert.
#
# Input FA paths are read from imaging_file_manifest.csv (PathFA).
# Only subjects with SubjectID starting with MLD are eligible.
# Warps are those generated by population_template, NOT later mrregister warps.

# -----------------------------
# SETTINGS
# -----------------------------
DATA_MASTER_DIR="${DATA_MASTER_DIR:-/home/chris/projects/mld_data_master_2026}"
MRTRIX_CONDA_ENV="${MRTRIX_CONDA_ENV:-mrtrix3}"
MRTRIX_NTHREADS="${MRTRIX_NTHREADS:-6}"
TEMPLATE_VOXEL_SIZE="${TEMPLATE_VOXEL_SIZE:-2.0}"
FA_INTERP="${FA_INTERP:-linear}"
MASK_TEMPLATE_FA="${MASK_TEMPLATE_FA:-1}"
EXPORT_TEMPLATE_FA_NIFTI="${EXPORT_TEMPLATE_FA_NIFTI:-1}"

INVENTORY="$DATA_MASTER_DIR/imaging_file_manifest.csv"
TPL_DIR="$DATA_MASTER_DIR/derivatives/fod_template_controls"
WARP_DIR="$TPL_DIR/warps"
TEMPLATE_REF="$TPL_DIR/wm_fod_template_${TEMPLATE_VOXEL_SIZE}mm.mif"
TEMPLATE_MASK="$TPL_DIR/template_mask_${TEMPLATE_VOXEL_SIZE}mm.mif"

OUT_DIR="$TPL_DIR/fa_template"
TEMP_DIR="$DATA_MASTER_DIR/derivatives/fa_template_temp"
XFM_FA_DIR="$TEMP_DIR/transformed_controls_fa"
FA_STACK_4D="$TEMP_DIR/transformed_controls_fa_stack_4d.mif"
TEMPLATE_FA_UNMASKED="$TEMP_DIR/template_FA_unmasked.mif"
TEMPLATE_FA="$OUT_DIR/template_FA_${TEMPLATE_VOXEL_SIZE}mm.mif"
TEMPLATE_FA_NII="$OUT_DIR/template_FA_${TEMPLATE_VOXEL_SIZE}mm.nii.gz"
LOG_PATH="$OUT_DIR/template_FA.log"
CONTROLS_USED="$OUT_DIR/controls_used.tsv"
INPUT_MANIFEST="$TEMP_DIR/controls_fa_inputs.tsv"

fail() { echo "ERROR: $*" >&2; exit 1; }

[[ -f "$INVENTORY" ]] || fail "Missing inventory: $INVENTORY"
[[ -d "$WARP_DIR" ]] || fail "Missing control-template warp directory: $WARP_DIR"
[[ -f "$TEMPLATE_REF" ]] || fail "Missing FOD template: $TEMPLATE_REF"
if [[ "$MASK_TEMPLATE_FA" == "1" ]]; then
    [[ -f "$TEMPLATE_MASK" ]] || fail "Missing template mask: $TEMPLATE_MASK"
fi

# Avoid accidentally mixing results from multiple runs. Temporary data are
# preserved after failure for debugging and may be removed as one directory.
if [[ -e "$TEMPLATE_FA" || -e "$TEMPLATE_FA_NII" ]]; then
    fail "An output FA template already exists in $OUT_DIR; move it before rerunning."
fi
if [[ -e "$TEMP_DIR" ]]; then
    fail "Temporary directory already exists: $TEMP_DIR. Inspect/remove it before rerunning."
fi

command -v python3 >/dev/null 2>&1 || fail "python3 not found"
if [[ -n "$MRTRIX_CONDA_ENV" ]]; then
    command -v conda >/dev/null 2>&1 || fail "conda not found"
    eval "$(conda shell.bash hook)"
    conda activate "$MRTRIX_CONDA_ENV"
fi
for tool in mrtransform mrcat mrmath mrcalc mrconvert; do
    command -v "$tool" >/dev/null 2>&1 || fail "MRtrix command not found: $tool"
done
export MRTRIX_NTHREADS

mkdir -p "$OUT_DIR" "$XFM_FA_DIR"

# A Python CSV reader avoids quoting and CRLF issues. Emit a UNIX-line-ending
# TSV containing one row for every control session, including missing inputs.
python3 - "$INVENTORY" "$DATA_MASTER_DIR" "$WARP_DIR" "$INPUT_MANIFEST" <<'PY'
import csv
import pathlib
import sys

inventory, root, warp_dir, destination = map(pathlib.Path, sys.argv[1:])
with inventory.open(newline="", encoding="utf-8-sig") as f:
    rows = list(csv.DictReader(f))

required = {"SubjectID", "SessionID", "PathFA"}
missing = required - set(rows[0].keys() if rows else [])
if missing:
    raise SystemExit(f"Missing inventory columns: {', '.join(sorted(missing))}")

seen = set()
controls = []
for row in rows:
    subject = (row.get("SubjectID") or "").strip()
    session = (row.get("SessionID") or "").strip()
    if not subject.startswith("MLD"):
        continue
    if not subject or not session:
        raise SystemExit(f"Control has missing SubjectID/SessionID: {row}")
    stem = f"sub-{subject}_ses-{session}"
    if stem in seen:
        raise SystemExit(f"Duplicate control session in inventory: {stem}")
    seen.add(stem)
    fa_str = (row.get("PathFA") or "").strip()
    fa = pathlib.Path(fa_str) if fa_str else None
    if fa is not None and not fa.is_absolute():
        fa = root / fa
    warp = warp_dir / f"{stem}_FOD_wm_norm.mif"
    controls.append((subject, session, stem, str(fa) if fa else "<MISSING>", str(warp)))

if not controls:
    raise SystemExit("No MLD controls found in inventory")

with destination.open("w", newline="", encoding="utf-8") as f:
    w = csv.writer(f, delimiter="\t", lineterminator="\n")
    w.writerow(["SubjectID", "SessionID", "Stem", "PathFA", "ControlTemplateWarp"])
    w.writerows(controls)
print(f"Found {len(controls)} control sessions in inventory")
PY

{
    echo "=== Healthy-control mean FA template ==="
    echo "Started: $(date -Is)"
    echo "Inventory: $INVENTORY"
    echo "Control warps: $WARP_DIR"
    echo "Reference: $TEMPLATE_REF"
    echo "Template mask: $TEMPLATE_MASK"
    echo "Temporary files: $TEMP_DIR"
    echo "Threads: $MRTRIX_NTHREADS"
    echo "Interpolation: $FA_INTERP"
    echo
} > "$LOG_PATH"

printf 'SubjectID\tSessionID\tStem\tPathFA\tControlTemplateWarp\n' > "$CONTROLS_USED"

n_total=0
n_kept=0
n_missing_fa=0
n_missing_warp=0

while IFS=$'\t' read -r subject session stem fa_src warp; do
    [[ "$subject" == "SubjectID" ]] && continue
    n_total=$((n_total + 1))

    # Any missing control input can be skipped, just as in the original script.
    if [[ ! -f "$warp" ]]; then
        echo "WARNING: no population_template warp for $stem; skipping" | tee -a "$LOG_PATH" >&2
        n_missing_warp=$((n_missing_warp + 1))
        continue
    fi
    if [[ "$fa_src" == "<MISSING>" || ! -f "$fa_src" ]]; then
        echo "WARNING: missing PathFA file for $stem: ${fa_src:-<empty>}; skipping" | tee -a "$LOG_PATH" >&2
        n_missing_fa=$((n_missing_fa + 1))
        continue
    fi

    fa_out="$XFM_FA_DIR/${stem}_FA_in_template.mif"
    echo "Warping FA: $stem" | tee -a "$LOG_PATH"
    mrtransform "$fa_src" "$fa_out" \
        -warp_full "$warp" \
        -template "$TEMPLATE_REF" \
        -interp "$FA_INTERP" \
        -force >> "$LOG_PATH" 2>&1

    printf '%s\t%s\t%s\t%s\t%s\n' \
        "$subject" "$session" "$stem" "$fa_src" "$warp" >> "$CONTROLS_USED"
    n_kept=$((n_kept + 1))
done < "$INPUT_MANIFEST"

printf 'Controls in inventory: %s | Used: %s | Missing FA: %s | Missing warp: %s\n' \
    "$n_total" "$n_kept" "$n_missing_fa" "$n_missing_warp" | tee -a "$LOG_PATH"
[[ "$n_kept" -ge 3 ]] || fail "Too few transformed FA images: $n_kept (minimum 3)"

# Keep original averaging operations intact.
echo "Averaging transformed FA images..." | tee -a "$LOG_PATH"
mrcat "$XFM_FA_DIR"/*.mif -axis 3 "$FA_STACK_4D" -force >> "$LOG_PATH" 2>&1
mrmath "$FA_STACK_4D" mean -axis 3 "$TEMPLATE_FA_UNMASKED" -force >> "$LOG_PATH" 2>&1
if [[ "$MASK_TEMPLATE_FA" == "1" ]]; then
    mrcalc "$TEMPLATE_FA_UNMASKED" "$TEMPLATE_MASK" -mult "$TEMPLATE_FA" \
        -force >> "$LOG_PATH" 2>&1
else
    cp "$TEMPLATE_FA_UNMASKED" "$TEMPLATE_FA"
fi

if [[ "$EXPORT_TEMPLATE_FA_NIFTI" == "1" ]]; then
    mrconvert "$TEMPLATE_FA" "$TEMPLATE_FA_NII" -datatype float32 \
        -force >> "$LOG_PATH" 2>&1
fi

echo "Completed: $(date -Is)" | tee -a "$LOG_PATH"
echo "FA template: $TEMPLATE_FA"
[[ "$EXPORT_TEMPLATE_FA_NIFTI" == "1" ]] && echo "NIfTI: $TEMPLATE_FA_NII"
echo "Controls used: $CONTROLS_USED"
echo "Log: $LOG_PATH"
echo "Intermediate files (delete after QC): $TEMP_DIR"
